// Copies the governed council handler (x402/rfai-council/index.ts) into src/council.generated.ts
// and appends named exports the MCP server needs (input screen, policy header values).
// The handler code itself is copied byte for byte; the SHA-256 of the source is recorded so
// the MCP server reports exactly which governed council it runs.
//
// Run: node scripts/sync-council.mjs          (writes the file)
//      node scripts/sync-council.mjs --check  (fails if the generated file is stale)
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "..", "x402", "rfai-council", "index.ts");
const out = join(here, "..", "src", "council.generated.ts");

const code = readFileSync(src, "utf8");
const sha = createHash("sha256").update(code).digest("hex");
const generated =
  `// GENERATED by scripts/sync-council.mjs from x402/rfai-council/index.ts. Do not edit.\n` +
  `// Source SHA-256: ${sha}\n` +
  code +
  `\n// ---- appended by scripts/sync-council.mjs ----\n` +
  `export const COUNCIL_SOURCE_SHA256 = "${sha}";\n` +
  `export { inputScreen, governanceHeader, ENDPOINT_VERSION, POLICY, MAX_TASK_CHARS, MAX_GRANTS, MAX_JOB_ID_CHARS };\n`;

if (process.argv.includes("--check")) {
  if (!existsSync(out) || readFileSync(out, "utf8") !== generated) {
    console.error("src/council.generated.ts is stale: run node scripts/sync-council.mjs");
    process.exit(1);
  }
  console.log(`council.generated.ts is current (source ${sha})`);
} else {
  writeFileSync(out, generated);
  console.log(`wrote src/council.generated.ts (source ${sha})`);
}
